const { app, BrowserWindow, ipcMain, Menu, nativeTheme } = require('electron');
const isDev = require('electron-is-dev');
const path = require('path');
const { getApiUrl, getWebUrl, WINDOW_SIZES, IPC_CHANNELS } = require('../electron/constants.js');

let mainWindow;

/**
 * Create the main application window
 */
function createWindow() {
  mainWindow = new BrowserWindow({
    width: WINDOW_SIZES.DEFAULT_WIDTH,
    height: WINDOW_SIZES.DEFAULT_HEIGHT,
    minWidth: WINDOW_SIZES.MIN_WIDTH,
    minHeight: WINDOW_SIZES.MIN_HEIGHT,
    webPreferences: {
      // SECURITY: Use preload script for safe IPC
      preload: path.join(__dirname, '../electron/preload.js'),
      nodeIntegration: false,        // CRITICAL: Disable direct node access
      contextIsolation: true,         // CRITICAL: Isolate context
      enableRemoteModule: false,      // SECURITY: Disable remote module
      sandbox: true,                  // SECURITY: Enable sandbox
    },
    icon: path.join(__dirname, 'public/app-icon.png'), // TODO: Add app icons
  });

  // Load app URL
  const startUrl = isDev
    ? 'http://localhost:3000'  // Dev: Connect to Vite dev server
    : `file://${path.join(__dirname, '../../citi-nati-frontend/dist/index.html')}`; // Prod: Load built frontend

  mainWindow.loadURL(startUrl);

  // Open DevTools in development
  if (isDev) {
    mainWindow.webContents.openDevTools();
  }

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

/**
 * IPC Handlers - Window Management
 */
ipcMain.on(IPC_CHANNELS.WINDOW_MINIMIZE, () => {
  if (mainWindow) mainWindow.minimize();
});

ipcMain.on(IPC_CHANNELS.WINDOW_MAXIMIZE, () => {
  if (mainWindow) {
    mainWindow.isMaximized() ? mainWindow.unmaximize() : mainWindow.maximize();
  }
});

ipcMain.on(IPC_CHANNELS.WINDOW_CLOSE, () => {
  if (mainWindow) mainWindow.close();
});

ipcMain.on(IPC_CHANNELS.WINDOW_FOCUS, () => {
  if (mainWindow) mainWindow.focus();
});

ipcMain.on(IPC_CHANNELS.WINDOW_OPEN_DEV_TOOLS, () => {
  if (mainWindow && isDev) mainWindow.webContents.openDevTools();
});

/**
 * IPC Handlers - App Info
 */
ipcMain.handle(IPC_CHANNELS.APP_GET_INFO, async () => {
  return {
    appVersion: app.getVersion(),
    electronVersion: process.versions.electron,
    nodeVersion: process.versions.node,
    platform: process.platform,
    isDev,
    apiUrl: getApiUrl(),
  };
});

/**
 * IPC Handlers - Auth Token Storage
 * NOTE: Tokens should be stored securely - consider using keytar or secure storage
 */
ipcMain.handle(IPC_CHANNELS.AUTH_GET_TOKEN, async () => {
  // TODO: Implement secure token retrieval from secure storage
  // For now, return from electron store (NOT PRODUCTION SAFE)
  return null;
});

ipcMain.handle('auth:saveToken', async (event, token) => {
  // TODO: Implement secure token storage using keytar or electron-store
  return true;
});

/**
 * IPC Handlers - Sync Operations
 */
ipcMain.handle(IPC_CHANNELS.SYNC_START, async (event, syncType) => {
  console.log(`[IPC] Starting sync: ${syncType}`);
  // TODO: Implement sync logic or relay to API
  
  // Example: Emit status updates
  mainWindow?.webContents.send(IPC_CHANNELS.SYNC_STATUS, {
    status: 'started',
    type: syncType,
  });
  
  return { success: true };
});

/**
 * IPC Handlers - Notifications
 */
ipcMain.on(IPC_CHANNELS.NOTIFICATION_SEND, (event, { title, options }) => {
  console.log(`[IPC] Notification: ${title}`, options);
  // TODO: Integrate with native OS notifications
});

/**
 * IPC Handlers - App Ready Signal
 */
ipcMain.on(IPC_CHANNELS.APP_READY, () => {
  console.log('[IPC] App ready signal received from renderer');
});

/**
 * App Lifecycle
 */
app.on('ready', createWindow);

app.on('window-all-closed', () => {
  // On macOS, keep app active until explicitly quit
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  // On macOS, re-create window when dock icon is clicked
  if (mainWindow === null) {
    createWindow();
  }
});

/**
 * Create application menu
 */
function createMenu() {
  const template = [
    {
      label: 'File',
      submenu: [
        {
          label: 'Exit',
          accelerator: 'CmdOrCtrl+Q',
          click: () => app.quit(),
        },
      ],
    },
    {
      label: 'Edit',
      submenu: [
        { label: 'Undo', accelerator: 'CmdOrCtrl+Z', role: 'undo' },
        { label: 'Redo', accelerator: 'CmdOrCtrl+Y', role: 'redo' },
        { type: 'separator' },
        { label: 'Cut', accelerator: 'CmdOrCtrl+X', role: 'cut' },
        { label: 'Copy', accelerator: 'CmdOrCtrl+C', role: 'copy' },
        { label: 'Paste', accelerator: 'CmdOrCtrl+V', role: 'paste' },
      ],
    },
    {
      label: 'View',
      submenu: [
        { label: 'Reload', accelerator: 'CmdOrCtrl+R', role: 'reload' },
        { label: 'Force Reload', accelerator: 'CmdOrCtrl+Shift+R', role: 'forceReload' },
        { label: 'Toggle DevTools', accelerator: 'CmdOrCtrl+I', role: 'toggleDevTools' },
      ],
    },
  ];

  Menu.setApplicationMenu(Menu.buildFromTemplate(template));
}

app.on('ready', createMenu);
